INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019s-am-41','exam-sg','インシデント管理','standard','single_choice','【平成31年度 春期 午前 問41】あるデータセンタでは受発注管理システムの運用サービスを提供している。夜間バッチ処理で注文トランザクションデータから注文書を出力するプログラムが異常終了した。運用担当者が検知し，保守担当者が緊急出社してサービスを回復し，後日プログラムの誤りを修正した。この事象のうちインシデントに該当するものはどれか。','[{"id":"a","text":"異常終了の検知"},{"id":"b","text":"プログラムの誤り"},{"id":"c","text":"プログラムの異常終了"},{"id":"d","text":"保守担当者の緊急出社"}]','"c"','サービスの中断や品質低下を引き起こす事象がインシデントであり，ここではプログラムの異常終了。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-42','exam-sg','システム運用・データ管理','standard','single_choice','【平成31年度 春期 午前 問42】システム運用におけるデータの取扱いに関する記述のうち，最も適切なものはどれか。','[{"id":"a","text":"エラーデータの修正は，データ発生元で行うものと運用部門で行うものに分けて実施する"},{"id":"b","text":"原始データの信ぴょう性のチェック及び原始データの受渡し管理は，運用部門が担当するのがよい"},{"id":"c","text":"データ発生元での修正は時間が掛かるので，エラーデータの修正はできるだけ運用部門に任せる方がよい"},{"id":"d","text":"入力データのエラー検出は，データ処理段階より入力段階で行った方が検出及び修正の作業効率がよい"}]','"d"','入力段階でエラーを検出すれば，早期に修正でき，後続処理での手戻りを減らせる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-43','exam-sg','プロジェクトマネジメント','standard','single_choice','【平成31年度 春期 午前 問43】組織が実施する作業を，プロジェクトと定常業務の二つに類別するとき，プロジェクトに該当するものはどれか。','[{"id":"a","text":"企業の経理部門が行う月次・半期・年次の決算処理"},{"id":"b","text":"金融機関の各支店が行う個人顧客向け住宅ローンの貸付け"},{"id":"c","text":"精密機器の製造販売企業が行う製品の取扱方法に関する問合せへの対応"},{"id":"d","text":"地方公共団体が行う庁舎の建替え"}]','"d"','庁舎の建替えは期限と固有の成果物がある一時的な取組であり，プロジェクトに該当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-44','exam-sg','クライアントサーバシステム','standard','single_choice','【平成31年度 春期 午前 問44】クライアントサーバシステムの特徴として，適切なものはどれか。','[{"id":"a","text":"クライアントとサーバが協調して目的の処理を遂行する分散処理形態であり，サービスという概念で機能を分割し，サーバがサービスを提供する"},{"id":"b","text":"クライアントとサーバが共通のデータ資源にアクセスするため，システム構成として密結合システムを採用している"},{"id":"c","text":"クライアントは多くのサーバからの要求に対して互いに協調して同時にサービスを提供し，サーバからのクライアント資源へのアクセスを制御する"},{"id":"d","text":"サービスを提供するクライアント内に設置するデータベースも，規模に対応して柔軟に拡大できる"}]','"a"','クライアントはサービスを要求し，サーバはサービスを提供する役割分担をもつ分散処理形態。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-45','exam-sg','データベース・排他制御','standard','single_choice','【平成31年度 春期 午前 問45】トランザクションT1が更新中のデータを，トランザクションT2が参照しようとしたとき，更新と参照の処理結果を矛盾させないようにするためのDBMSの機能はどれか。','[{"id":"a","text":"最適化"},{"id":"b","text":"参照制約"},{"id":"c","text":"排他制御"},{"id":"d","text":"副問合せ"}]','"c"','排他制御は同時アクセスによるデータの矛盾を防ぐため，ロックなどで処理を調整する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-46','exam-sg','メールプロトコル','standard','single_choice','【平成31年度 春期 午前 問46】PCで電子メールの送受信を行う際，電子メールの送信とメールサーバからの受信に使用するプロトコルの組合せとして，適切なものはどれか。','[{"id":"a","text":"送信IMAP4／受信POP3"},{"id":"b","text":"送信IMAP4／受信SMTP"},{"id":"c","text":"送信POP3／受信IMAP4"},{"id":"d","text":"送信SMTP／受信IMAP4"}]','"d"','メール送信にはSMTPを使い，受信にはPOP3またはIMAP4を使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-47','exam-sg','業務プロセス・BPO','standard','single_choice','【平成31年度 春期 午前 問47】BPOの説明はどれか。','[{"id":"a","text":"災害や事故で被害を受けても重要事業を中断させない，又は中断期間を短くする仕組みを構築すること"},{"id":"b","text":"社内業務のうちコアビジネスでない業務の一部又は全部を，外部の専門企業に委託すること"},{"id":"c","text":"製品の基準生産計画，部品表及び在庫情報を基に資材所要量と必要時期を求める生産管理手法"},{"id":"d","text":"プロジェクトを戦略適合性，費用対効果，リスクなどで評価し，情報化投資のバランスを管理すること"}]','"b"','BPOは業務プロセスの一部または全部を外部の専門企業へ委託すること。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-48','exam-sg','投資回収期間・年間利益','standard','single_choice','【平成31年度 春期 午前 問48】IT機器a，bの投資額と回収期間は，aが90万円・3年，bが300万円・5年である。利益は毎年均等で，利率は考慮しない。設定期間内に投資額を回収するために必要な最低年間利益について，適切な記述はどれか。','[{"id":"a","text":"aとbは同額の年間利益が必要である"},{"id":"b","text":"aはbの2倍の年間利益が必要である"},{"id":"c","text":"bはaの1.5倍の年間利益が必要である"},{"id":"d","text":"bはaの2倍の年間利益が必要である"}]','"d"','aは90÷3＝30万円/年，bは300÷5＝60万円/年なので，bはaの2倍。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-49','exam-sg','調達・ベンダ選定','standard','single_choice','【平成31年度 春期 午前 問49】RFIに回答した各ベンダに対してRFPを提示した。今後のベンダ選定に当たって，公正に手続を進めるためにあらかじめ実施しておくことはどれか。','[{"id":"a","text":"RFIの回答評価が高いベンダに，選定から外れた場合の再提案救済措置を講じる"},{"id":"b","text":"現行システムを熟知したベンダを選定しやすいよう，RFP要求事項とは別に評価を高くしておく"},{"id":"c","text":"提案の評価基準や要求事項への適合度の重み付けなど，選定基準や手順を確立しておく"},{"id":"d","text":"選定から契約までの期間短縮のため，RFPを提示した全ベンダに内示書を発行し契約書作成を依頼する"}]','"c"','選定の公平性・透明性を保つため，評価基準と手順をあらかじめ定める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-50','exam-sg','企業の社会的責任・環境対策','standard','single_choice','【平成31年度 春期 午前 問50】企業が社会的責任を果たすために実施すべき施策のうち，環境対策の観点から実施するものはどれか。','[{"id":"a","text":"株主に対し，企業の経営状況の透明化を図る"},{"id":"b","text":"グリーン購入に向けて社内体制を整備する"},{"id":"c","text":"災害時における従業員のボランティア活動を支援する制度を構築する"},{"id":"d","text":"社内に倫理ヘルプラインを設置する"}]','"b"','グリーン購入は環境負荷の少ない製品・サービスを優先して調達する取組。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja');
